int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }
    int result = 0;
    for (int i = 0; i < n; i++) {
        int value;
        if (scanf("%d", &value) != 1) {
            break;
        }
        result ^= value;
    }
    printf("%d\n", result);
    return 0;
}

