#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>

int main(void) {
    uint32_t a, b;
    while (scanf("%" SCNu32 " %" SCNu32, &a, &b) == 2) {
        uint32_t diff = a ^ b;
        int positions[32];
        int count = 0;
        for (int i = 0; i < 32; i++) {
            if ((diff >> i) & 1u) {
                positions[count++] = i;
            }
        }
        printf("%d", count);
        if (count > 0) {
            printf(":");
            for (int i = 0; i < count; i++) {
                printf(" %d", positions[i]);
            }
        }
        printf("\n");
    }
    return 0;
}

