#include <stdio.h>

static void swap(int *a, int *b) {      // обмен без временной переменной
    *a ^= *b;
    *b ^= *a;
    *a ^= *b;
}

static void reverse(int *values, int left, int right) {
    for (int i = left, j = right; i <= j; i++, j--) {
        swap(&values[i], &values[j]);
    }
}

int main(void) {
    int n, values[100];
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &values[i]) != 1) {
            return 0;
        }
    }
    int left, right;
    while (scanf("%d %d", &left, &right) == 2) {
        if (left >= 0 && left <= right && right < n) {
            reverse(values, left, right);
        }
    }
    for (int i = 0; i < n; i++) {
        printf(i + 1 < n ? "%d " : "%d\n", values[i]);
    }
    return 0;
}

