#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char line[128];
    while (fgets(line, sizeof line, stdin) != NULL) {
        line[strcspn(line, "\r\n")] = '\0';
        if (line[0] != '$') {
            printf("ошибка: нет $\n");
            continue;
        }
        const char *star = strchr(line, '*');
        if (star == NULL) {
            printf("нет контрольной суммы\n");
            continue;
        }
        if (strlen(star + 1) != 2 || !isxdigit((unsigned char)star[1]) ||
            !isxdigit((unsigned char)star[2])) {
            printf("ошибка: неверная контрольная сумма\n");
            continue;
        }
        unsigned sum = 0;
        for (const char *p = line + 1; p < star; p++) {
            sum ^= (unsigned char)*p;
        }
        unsigned expected = (unsigned)strtol(star + 1, NULL, 16);
        if (sum == expected) {
            size_t type_len = strcspn(line + 1, ",*");
            printf("OK %.*s\n", (int)type_len, line + 1);
        } else {
            printf("ошибка: ожидалось %02X, вычислено %02X\n", expected, sum);
        }
    }
    return 0;
}

